-- OLA12 · HN:LEY_LAVADO_ACTIVOS · lote OLA12_LA_2015_01 · 2026-11-24
-- DESTINO EXCLUSIVO: mayalex-ia-pinel-hn (producción) (thgrhueckkjdutjvcufp). El ejecutor verifica el project ref y la huella SHA-256 de este archivo antes de correrlo.
-- Activa V5 atómicamente (93 filas: 93 PRIMARY, 0 CONTEXT).

BEGIN;
DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LA_2015_01' AND metadata->>'norm_id' = 'HN:LEY_LAVADO_ACTIVOS'
    AND instrumento_id = 'LEY_LAVADO_ACTIVOS' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL AND embedding IS NOT NULL AND embedding <> array_fill(0::real, ARRAY[384])::vector;
  IF n <> 93 THEN RAISE EXCEPTION 'precondición V5: % filas (esperadas 93)', n; END IF;
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA12_LA_2015_01';
  IF n <> 93 THEN RAISE EXCEPTION 'filas extra en el lote: % (esperadas 93)', n; END IF;
  UPDATE public.biblioteca_vectores SET revision_pendiente = false, es_norma_vigente = true,
    metadata = (metadata - 'rol' - 'clasificacion_propuesta') || jsonb_build_object('estado_v', 'V5', 'vigencia', 'TRUE_PRESUNTA', 'revision_pendiente', false, 'motivo_rol', 'PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)', 'adjudicacion', 'EXPEDIENTE_AUDITORIA_LA_OLA12.md (D1–D8)', 'promocion_fecha', '2026-11-24', 'promocion_ola', 'OLA12')
  WHERE ingest_batch = 'OLA12_LA_2015_01' AND id IN ('OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:1', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:2', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:3', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:4', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:5', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:6', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:7', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:8', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:9', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:10', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:11', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:12', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:13', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:14', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:15', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:16', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:17', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:18', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:19', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:20', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:21', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:22', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:23', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:24', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:25', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:26', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:27', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:28', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:29', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:30', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:31', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:32', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:33', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:34', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:35', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:36', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:37', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:38', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:39', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:40', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:41', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:42', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:43', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:44', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:45', 'OLA12_LA_2015_01:LEY_LAVADO_ACTIVOS:46', 'OLA12_LA_2015_01:LEY_LA